package com.srent.payment;
import com.srent.audit.AuditService; import com.srent.booking.*; import com.srent.common.ApiException; import com.srent.security.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/payments") @RequiredArgsConstructor
public class PaymentController {
    private final PaymentRepository payments;private final BookingRepository bookings;private final PaymentProvider provider;private final AuditService audit;
    public record Request(@NotNull UUID bookingId,@NotNull @DecimalMin("1000")BigDecimal amount){}public record Response(UUID id,UUID bookingId,BigDecimal amount,String currency,Payment.Status status,String provider,String providerReference,boolean simulated,String notice,Instant createdAt){public static Response from(Payment p){return new Response(p.getId(),p.getBooking().getId(),p.getAmount(),p.getCurrency(),p.getStatus(),p.getProvider(),p.getProviderReference(),true,"Thanh toán mô phỏng; hệ thống không giữ tiền thật",p.getCreatedAt());}}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('STUDENT')") @Transactional public Response create(@Valid @RequestBody Request q){var b=bookings.findById(q.bookingId()).orElseThrow(()->ApiException.notFound("Booking"));if(!b.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Booking không thuộc bạn");if(b.getStatus()!=Booking.Status.ACCEPTED)throw ApiException.conflict("BOOKING_NOT_ACCEPTED","Booking chưa được chấp nhận");if(payments.existsByBookingIdAndStatusIn(b.getId(),List.of(Payment.Status.PENDING,Payment.Status.HELD)))throw ApiException.conflict("ACTIVE_PAYMENT_EXISTS","Booking đã có giao dịch đang hoạt động");var p=new Payment();p.setBooking(b);p.setStudent(b.getStudent());p.setLandlord(b.getLandlord());p.setAmount(q.amount());p.setProvider(provider.name());p.setProviderReference("pending_"+UUID.randomUUID());payments.save(p);var result=provider.create(p.getId(),p.getAmount());p.setProviderReference(result.reference());audit.log(CurrentUser.id(),"MOCK_PAYMENT_CREATED","PAYMENT",p.getId(),result.message());return Response.from(p);}
    @PostMapping("/{id}/confirm") @PreAuthorize("hasRole('STUDENT')") @Transactional public Response confirm(@PathVariable UUID id){var p=owned(id);if(p.getStatus()==Payment.Status.HELD)return Response.from(p);if(p.getStatus()!=Payment.Status.PENDING)throw ApiException.conflict("INVALID_PAYMENT_STATE","Không thể xác nhận trạng thái hiện tại");var result=provider.confirm(p.getProviderReference());p.setStatus(result.success()?Payment.Status.HELD:Payment.Status.FAILED);audit.log(CurrentUser.id(),"MOCK_PAYMENT_CONFIRMED","PAYMENT",id,result.message());return Response.from(p);}
    @PostMapping("/{id}/refund") @Transactional public Response refund(@PathVariable UUID id){var p=access(id);if(p.getStatus()==Payment.Status.REFUNDED)return Response.from(p);if(p.getStatus()!=Payment.Status.HELD)throw ApiException.conflict("INVALID_PAYMENT_STATE","Chỉ khoản HELD mô phỏng mới hoàn được");p.setStatus(Payment.Status.REFUNDED);audit.log(CurrentUser.id(),"MOCK_PAYMENT_REFUNDED","PAYMENT",id,null);return Response.from(p);}
    @PostMapping("/{id}/release") @PreAuthorize("hasRole('ADMIN')") @Transactional public Response release(@PathVariable UUID id){var p=payments.findById(id).orElseThrow(()->ApiException.notFound("Thanh toán"));if(p.getStatus()==Payment.Status.RELEASED)return Response.from(p);if(p.getStatus()!=Payment.Status.HELD)throw ApiException.conflict("INVALID_PAYMENT_STATE","Chỉ khoản HELD mô phỏng mới giải ngân được");p.setStatus(Payment.Status.RELEASED);audit.log(CurrentUser.id(),"MOCK_PAYMENT_RELEASED","PAYMENT",id,null);return Response.from(p);}
    @GetMapping("/my") public Page<Response> mine(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return payments.findAllByStudentIdOrLandlordId(CurrentUser.id(),CurrentUser.id(),p).map(Response::from);}
    private Payment owned(UUID id){var p=payments.findById(id).orElseThrow(()->ApiException.notFound("Thanh toán"));if(!p.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Giao dịch không thuộc bạn");return p;}private Payment access(UUID id){var p=payments.findById(id).orElseThrow(()->ApiException.notFound("Thanh toán"));UUID u=CurrentUser.id();if(!p.getStudent().getId().equals(u)&&!p.getLandlord().getId().equals(u)&&CurrentUser.principal().role()!=com.srent.user.User.Role.ADMIN)throw ApiException.forbidden("Không có quyền truy cập giao dịch");return p;}
}
